INSERT INTO products (id, name, description, price, sale_price, image_url, brand, sku, slug, category_id, active, specifications, created_at, updated_at) VALUES
(1, 'Laptop ASUS Vivobook 14 X1404VA-NK123W', 'Laptop ASUS Vivobook 14 mỏng nhẹ, hiệu năng văn phòng tốt với chip Core i3 thế hệ 12.', 12490000, 10990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080027/techshop/products/product_1.png', 'ASUS', 'ASUS-X1404VA', 'asus-vivobook-14-x1404va', 1, 1, '{"CPU":"Intel Core i3-1215U","RAM":"8GB DDR4","SSD":"256GB NVMe","Màn hình":"14.0 inch FHD IPS","Trọng lượng":"1.4 kg","Pin":"42Wh"}', NOW(), NOW()),
(2, 'Laptop HP Pavilion 15-eg3093TU', 'Thiết kế kim loại sang trọng, màn hình viền mỏng sắc nét phù hợp cho sinh viên và người làm văn phòng.', 18990000, 16990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080031/techshop/products/product_2.png', 'HP', 'HP-PAVILION-15', 'hp-pavilion-15-eg3093tu', 1, 1, '{"CPU":"Intel Core i5-1335U","RAM":"16GB DDR4","SSD":"512GB NVMe","Màn hình":"15.6 inch FHD IPS","Trọng lượng":"1.74 kg","Pin":"41Wh"}', NOW(), NOW()),
(3, 'Laptop Lenovo ThinkBook 14 G6+ IMH', 'ThinkBook siêu bền, bàn phím gõ êm ái hàng đầu, trang bị chip Intel Core Ultra mới nhất.', 22990000, 20990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080035/techshop/products/product_3.png', 'Lenovo', 'LENOVO-TB14G6', 'lenovo-thinkbook-14-g6', 1, 1, '{"CPU":"Intel Core Ultra 5-125H","RAM":"16GB LPDDR5X","SSD":"512GB NVMe","Màn hình":"14.0 inch 2.5K 90Hz","Trọng lượng":"1.43 kg","Pin":"60Wh"}', NOW(), NOW()),
(4, 'Laptop Dell Inspiron 15 3530 i5 1334U', 'Dell Inspiron 15 dáng mỏng nhẹ, thiết kế tinh tế, hiệu năng ổn định cho sinh viên và dân văn phòng.', 16990000, 15490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080040/techshop/products/product_4.png', 'Dell', 'DELL-INS-3530', 'dell-inspiron-15-3530', 1, 1, '{"CPU":"Intel Core i5-1334U","RAM":"16GB DDR4","SSD":"512GB NVMe","Màn hình":"15.6 inch FHD 120Hz","Trọng lượng":"1.65 kg","Pin":"54Wh"}', NOW(), NOW()),
(5, 'Laptop Acer Aspire 5 A515-58P-77AP', 'Aspire 5 nâng cấp toàn diện: màn hình IPS sắc nét, RAM lớn, SSD nhanh, thời lượng pin vượt trội.', 14990000, 13490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080042/techshop/products/product_5.png', 'Acer', 'ACER-A515-58P', 'acer-aspire-5-a515-58p', 1, 1, '{"CPU":"Intel Core i5-1335U","RAM":"8GB DDR4","SSD":"512GB NVMe","Màn hình":"15.6 inch FHD IPS","Trọng lượng":"1.77 kg","Pin":"50Wh"}', NOW(), NOW()),
(6, 'Laptop MSI Modern 14 C12M-258VN', 'MSI Modern 14 mỏng nhẹ chỉ 1.4 kg, màu sắc tinh tế, đáp ứng mọi tác vụ văn phòng và học tập hằng ngày.', 15490000, 13990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080044/techshop/products/product_6.png', 'MSI', 'MSI-MODERN-14', 'msi-modern-14-c12m', 1, 1, '{"CPU":"Intel Core i5-1235U","RAM":"8GB DDR4","SSD":"512GB NVMe","Màn hình":"14.0 inch FHD IPS 60Hz","Trọng lượng":"1.4 kg","Pin":"52Wh"}', NOW(), NOW()),
(57, 'Laptop LG Gram 16 2024 16Z90S-G.AH55A5', 'LG Gram siêu nhẹ chỉ 1.19kg với khung magie bền bỉ, màn hình 16 inch WQXGA sắc nét và pin lên đến 25 giờ.', 31990000, 28990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081417/techshop/products/product_57.jpg', 'LG', 'LG-GRAM-16-2024', 'lg-gram-16-2024-ah55a5', 1, 1, '{"CPU":"Intel Core Ultra 5-125H","RAM":"16GB LPDDR5X","SSD":"512GB NVMe","Màn hình":"16 inch WQXGA IPS 120Hz","Trọng lượng":"1.19 kg","Pin":"80Wh"}', NOW(), NOW()),
(58, 'Laptop ASUS Zenbook 14 OLED UX3405MA', 'Zenbook 14 OLED màn hình sống động 2.8K 120Hz, hiệu năng Core Ultra vượt trội trong thiết kế siêu mỏng 1.2kg.', 29990000, 26990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081424/techshop/products/product_58.png', 'ASUS', 'ASUS-UX3405MA', 'asus-zenbook-14-oled-ux3405ma', 1, 1, '{"CPU":"Intel Core Ultra 5-125H","RAM":"16GB LPDDR5X","SSD":"512GB NVMe","Màn hình":"14 inch 2.8K OLED 120Hz","Trọng lượng":"1.2 kg","Pin":"75Wh"}', NOW(), NOW()),
(59, 'Laptop HP Envy 13-ba1537TU', 'HP Envy 13 thiết kế cao cấp, màn hình cảm ứng Full HD, bảo mật vân tay và nhận diện khuôn mặt tiện lợi.', 22990000, 20490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081427/techshop/products/product_59.png', 'HP', 'HP-ENVY-13-BA1537', 'hp-envy-13-ba1537tu', 1, 1, '{"CPU":"Intel Core i7-1165G7","RAM":"16GB LPDDR4X","SSD":"512GB NVMe","Màn hình":"13.3 inch FHD IPS Touch","Trọng lượng":"1.28 kg","Pin":"51Wh"}', NOW(), NOW()),
(60, 'Laptop Dell XPS 13 Plus 9320', 'Dell XPS 13 Plus đỉnh cao thiết kế, màn hình OLED+ rực rỡ cho sáng tạo nội dung.', 39990000, 36990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081430/techshop/products/product_60.png', 'Dell', 'DELL-XPS-9320', 'dell-xps-13-plus-9320', 1, 1, '{"CPU":"Intel Core i7-1280P","RAM":"16GB LPDDR5","SSD":"512GB NVMe","Màn hình":"13.4 inch FHD+ InfinityEdge","Trọng lượng":"1.26 kg","Pin":"55Wh"}', NOW(), NOW()),
(7, 'Laptop Gaming ASUS TUF Gaming A15 FA507NU-LP034W', 'Chiến binh gaming quốc dân với card đồ họa RTX 4050 mạnh mẽ và màn hình 144Hz mượt mà.', 26990000, 23990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080047/techshop/products/product_7.png', 'ASUS', 'ASUS-TUF-A15', 'asus-tuf-gaming-a15-fa507nu', 2, 1, '{"CPU":"AMD Ryzen 5 7535HS","RAM":"16GB DDR5","SSD":"512GB NVMe","VGA":"NVIDIA RTX 4050 6GB","Màn hình":"15.6 inch FHD 144Hz","Pin":"90Wh"}', NOW(), NOW()),
(8, 'Laptop Gaming Acer Nitro V ANV15-51-57B4', 'Nitro V thế hệ mới sở hữu thiết kế vuông vắn, tản nhiệt kép và cấu hình mạnh mẽ.', 23490000, 21490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080049/techshop/products/product_8.jpg', 'Acer', 'ACER-NITRO-V', 'acer-nitro-v-anv15', 2, 1, '{"CPU":"Intel Core i5-13420H","RAM":"8GB DDR5","SSD":"512GB NVMe","VGA":"NVIDIA RTX 4050 6GB","Màn hình":"15.6 inch FHD 144Hz","Pin":"57Wh"}', NOW(), NOW()),
(9, 'Laptop Gaming Lenovo LOQ 15IAX9 83GS001RVN', 'LOQ thừa hưởng thiết kế cao cấp từ dòng Legion danh tiếng, hiệu năng cực đỉnh trong tầm giá.', 21990000, 19990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080051/techshop/products/product_9.jpg', 'Lenovo', 'LENOVO-LOQ-15', 'lenovo-loq-15iax9', 2, 1, '{"CPU":"Intel Core i5-12450HX","RAM":"12GB DDR5","SSD":"512GB NVMe","VGA":"NVIDIA RTX 3050 6GB","Màn hình":"15.6 inch FHD 144Hz","Pin":"60Wh"}', NOW(), NOW()),
(10, 'Laptop Gaming Acer Aspire 7 A715-57G-57YJ', 'Acer Aspire 7 16GB RAM đa nhiệm mạnh mẽ, RTX 3050 4GB, màn hình 144Hz sắc nét.', 19990000, 17990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080054/techshop/products/product_10.png', 'Acer', 'LGM003', 'acer-aspire-7-a715-57g', 2, 1, '{"CPU":"Intel Core i5-12450H","RAM":"16GB DDR4","SSD":"512GB NVMe","VGA":"NVIDIA RTX 3050 4GB","Màn hình":"15.6 inch FHD 144Hz","Pin":"55Wh"}', NOW(), NOW()),
(11, 'Laptop Gaming MSI Thin GF63 12UC-897VN', 'Thiết kế mỏng nhẹ ấn tượng chỉ 1.86 kg, card RTX 3050 đủ sức chiến đa số game hiện đại.', 17990000, 16490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080057/techshop/products/product_11.png', 'MSI', 'MSI-GF63-12UC', 'msi-thin-gf63-12uc', 2, 1, '{"CPU":"Intel Core i5-12450H","RAM":"8GB DDR4","SSD":"512GB NVMe","VGA":"NVIDIA RTX 3050 4GB","Màn hình":"15.6 inch FHD 144Hz","Trọng lượng":"1.86 kg"}', NOW(), NOW()),
(12, 'Laptop Gaming ASUS ROG Strix G16 G614JI-N4066W', 'ROG Strix G16 mạnh mẽ nhất dòng ROG phổ thông: RTX 4070 8GB, màn hình QHD 240Hz đỉnh cao.', 49990000, 44990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080061/techshop/products/product_12.png', 'ASUS', 'ASUS-ROG-G614JI', 'asus-rog-strix-g16-g614ji', 2, 1, '{"CPU":"Intel Core i9-13980HX","RAM":"16GB DDR5","SSD":"1TB NVMe","VGA":"NVIDIA RTX 4070 8GB","Màn hình":"16 inch QHD 240Hz","Trọng lượng":"2.3 kg"}', NOW(), NOW()),
(61, 'Laptop Gaming HP Omen 16-wf0129tx', 'HP Omen 16 trang bị RTX 4070 8GB mạnh mẽ, màn hình QHD 165Hz sắc nét, tản nhiệt Tempest Cooling đỉnh cao.', 41990000, 37990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081440/techshop/products/product_61.png', 'HP', 'HP-OMEN-16-WF0129', 'hp-omen-16-wf0129tx', 2, 1, '{"CPU":"Intel Core i9-13900HX","RAM":"16GB DDR5","SSD":"1TB NVMe","VGA":"NVIDIA RTX 4070 8GB","Màn hình":"16.1 inch QHD 165Hz","Trọng lượng":"2.47 kg"}', NOW(), NOW()),
(62, 'Laptop Gaming MSI Raider GE68 HX 13VG', 'MSI Raider GE68 flagship gaming: Core i9 thế hệ 13, RTX 4070 Ti, màn hình QHD 240Hz cực mượt.', 59990000, 54990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081446/techshop/products/product_62.png', 'MSI', 'MSI-RAIDER-GE68-13VG', 'msi-raider-ge68-hx-13vg', 2, 1, '{"CPU":"Intel Core i9-13980HX","RAM":"32GB DDR5","SSD":"1TB NVMe","VGA":"NVIDIA RTX 4070 Ti 12GB","Màn hình":"16 inch QHD 240Hz","Trọng lượng":"2.5 kg"}', NOW(), NOW()),
(63, 'Laptop Gaming ASUS ROG Zephyrus G14 GA403WM', 'ROG Zephyrus G14 2024 mỏng nhẹ nhất dòng gaming: AMD Ryzen AI 9 HX, RTX 4060, màn hình OLED 144Hz cực đỉnh.', 42990000, 38990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081450/techshop/products/product_63.png', 'ASUS', 'ASUS-G14-GA403WM', 'asus-rog-zephyrus-g14-ga403wm', 2, 1, '{"CPU":"AMD Ryzen AI 9 HX 370","RAM":"16GB LPDDR5X","SSD":"1TB NVMe","VGA":"NVIDIA RTX 4060 8GB","Màn hình":"14 inch 2.5K OLED 144Hz","Trọng lượng":"1.5 kg"}', NOW(), NOW()),
(64, 'Laptop Gaming Lenovo Legion 5 15IRX10', 'Legion 5 2024: Core i7-14650HX, RTX 4060 mạnh mẽ hơn, màn hình 144Hz, tản nhiệt Legion Coldfront 5.0.', 35990000, 32990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081461/techshop/products/product_64.png', 'Lenovo', 'LENOVO-LEGION5-15IRX10', 'lenovo-legion-5-15irx10', 2, 1, '{"CPU":"Intel Core i7-14650HX","RAM":"16GB DDR5","SSD":"512GB NVMe","VGA":"NVIDIA RTX 4060 8GB","Màn hình":"15.6 inch FHD 144Hz","Trọng lượng":"2.4 kg"}', NOW(), NOW());
INSERT INTO products (id, name, description, price, sale_price, image_url, brand, sku, slug, category_id, active, specifications, created_at, updated_at) VALUES
(13, 'PC TechShop Gaming GVN Minotaur i4060', 'Dàn PC lắp sẵn tối ưu cho nhu cầu chơi game Esport và đồ họa bán chuyên, card RTX 4060.', 20500000, 18900000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080064/techshop/products/product_13.jpg', 'TechShop', 'GVN-MINOTAUR-I4060', 'pc-techshop-gvn-minotaur-i4060', 3, 1, '{"CPU":"Intel Core i5-12400F","Main":"B760 DDR4","RAM":"16GB RGB 3200MHz","VGA":"NVIDIA RTX 4060 8GB","SSD":"512GB NVMe","Nguồn":"650W 80 Plus"}', NOW(), NOW()),
(14, 'PC TechShop Văn Phòng GVN Office i3', 'PC văn phòng nhỏ gọn, hoạt động ổn định, tiết kiệm điện năng cho văn phòng công ty.', 7500000, 6900000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080068/techshop/products/product_14.png', 'TechShop', 'GVN-OFFICE-I3', 'pc-techshop-gvn-office-i3', 3, 1, '{"CPU":"Intel Core i3-12100","Main":"H610 DDR4","RAM":"8GB 3200MHz","VGA":"Intel UHD 730","SSD":"256GB SATA III","Nguồn":"400W"}', NOW(), NOW()),
(15, 'PC TechShop Pro i5 5060 RTX', 'Bộ máy tính lắp ráp hiệu năng cao với RTX 5060, phục vụ rendering, game nặng và stream.', 29900000, 27900000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080071/techshop/products/product_15.jpg', 'TechShop', 'GVN-PRO-I5-5060', 'pc-techshop-pro-i5-5060', 3, 1, '{"CPU":"Intel Core i5-14600KF","Main":"B760 DDR5","RAM":"32GB DDR5 5600MHz","VGA":"NVIDIA RTX 5060 12GB","SSD":"1TB NVMe Gen4","Nguồn":"750W 80+ Gold"}', NOW(), NOW()),
(16, 'PC TechShop Workstation i7 4070', 'Máy trạm đồ họa chuyên nghiệp, phục vụ thiết kế 3D, render video 4K và AI xử lý hình ảnh.', 45900000, 42900000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080073/techshop/products/product_16.jpg', 'TechShop', 'GVN-WS-I7-4070', 'pc-techshop-workstation-i7', 3, 1, '{"CPU":"Intel Core i7-14700KF","Main":"Z790 DDR5","RAM":"32GB DDR5 6000MHz","VGA":"NVIDIA RTX 4070 Ti 12GB","SSD":"2TB NVMe Gen4","Nguồn":"850W 80+ Gold"}', NOW(), NOW()),
(17, 'PC TechShop Budget AMD Gaming', 'Bộ PC gaming tầm trung AMD, hiệu năng xuất sắc trong ngân sách, chiến game AAA ở Ultra 1080p.', 14900000, 13900000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080084/techshop/products/product_17.png', 'TechShop', 'GVN-AMD-BUDGET', 'pc-techshop-amd-budget', 3, 1, '{"CPU":"AMD Ryzen 5 5600","Main":"B550M DDR4","RAM":"16GB DDR4 3200MHz","VGA":"RX 6600 8GB","SSD":"512GB NVMe","Nguồn":"550W 80+ Bronze"}', NOW(), NOW()),
(18, 'Màn hình ASUS TUF Gaming VG249Q3A 24" IPS 180Hz', 'Tần số quét cao 180Hz, tấm nền IPS màu sắc chân thực, thời gian phản hồi 1ms GtG.', 4500000, 3690000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080086/techshop/products/product_18.jpg', 'ASUS', 'ASUS-VG249Q3A', 'man-hinh-asus-tuf-gaming-vg249q3a', 4, 1, '{"Kích thước":"23.8 inch","Tấm nền":"IPS","Độ phân giải":"FHD 1920x1080","Tần số quét":"180Hz","Thời gian phản hồi":"1ms GtG"}', NOW(), NOW()),
(19, 'Màn hình Dell UltraSharp U2422H 24" IPS FHD', 'Màn hình chuyên đồ họa viền siêu mỏng, độ chuẩn màu delta E < 2.', 6990000, 5990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080088/techshop/products/product_19.jpg', 'Dell', 'DELL-U2422H', 'man-hinh-dell-ultrasharp-u2422h', 4, 1, '{"Kích thước":"23.8 inch","Tấm nền":"IPS sRGB 100%","Độ phân giải":"FHD 1920x1080","Tần số quét":"60Hz","Cổng kết nối":"HDMI, DP, USB-C"}', NOW(), NOW()),
(20, 'Màn hình LG UltraGear 27GP850-B 27" Nano IPS 165Hz', 'Nano IPS 27 inch siêu mượt 165Hz, 1ms GtG, chuẩn màu HDR400 cho game thủ đỉnh cao.', 8490000, 7490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080090/techshop/products/product_20.jpg', 'LG', 'LG-27GP850-B', 'man-hinh-lg-ultragear-27gp850', 4, 1, '{"Kích thước":"27 inch","Tấm nền":"Nano IPS","Độ phân giải":"QHD 2560x1440","Tần số quét":"165Hz","Thời gian phản hồi":"1ms GtG"}', NOW(), NOW()),
(21, 'Màn hình Samsung Odyssey G4 S25BG400EE 25" IPS 240Hz', 'Samsung G4 tốc độ cực cao 240Hz, thiết kế hiện đại, dành cho game thủ FPS chuyên nghiệp.', 6490000, 5690000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080093/techshop/products/product_21.jpg', 'Samsung', 'SAM-S25BG400', 'man-hinh-samsung-odyssey-g4', 4, 1, '{"Kích thước":"25 inch","Tấm nền":"IPS","Độ phân giải":"FHD 1920x1080","Tần số quét":"240Hz","Thời gian phản hồi":"1ms GtG"}', NOW(), NOW()),
(22, 'Màn hình ViewSonic VX2758-2KP-MHD 27" IPS 144Hz', 'ViewSonic 27 inch 2K siêu nét, 144Hz mượt mà, lý tưởng cho game thủ và dân đồ họa.', 5990000, 5290000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080095/techshop/products/product_22.jpg', 'ViewSonic', 'VSN-VX2758-2KP', 'man-hinh-viewsonic-vx2758-2kp', 4, 1, '{"Kích thước":"27 inch","Tấm nền":"IPS","Độ phân giải":"QHD 2560x1440","Tần số quét":"144Hz","Thời gian phản hồi":"1ms GtG"}', NOW(), NOW()),
(23, 'Màn hình AOC 24G2SE 24" VA 165Hz', 'Màn hình gaming giá tốt, tấm nền VA cho màu đen sâu, 165Hz đủ mượt cho game thủ phổ thông.', 2990000, 2590000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080097/techshop/products/product_23.jpg', 'AOC', 'AOC-24G2SE', 'man-hinh-aoc-24g2se-165hz', 4, 1, '{"Kích thước":"23.8 inch","Tấm nền":"VA","Độ phân giải":"FHD 1920x1080","Tần số quét":"165Hz","Thời gian phản hồi":"1ms MPRT"}', NOW(), NOW()),
(65, 'Màn hình Gigabyte GS25F2A 25" IPS 240Hz', 'Gigabyte GS25F2A tốc độ cao 240Hz, hỗ trợ AMD FreeSync Premium, thời gian phản hồi 1ms MPRT cực nhanh.', 4290000, 3790000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081463/techshop/products/product_65.jpg', 'Gigabyte', 'GIGABYTE-GS25F2A', 'man-hinh-gigabyte-gs25f2a-240hz', 4, 1, '{"Kích thước":"24.5 inch","Tấm nền":"IPS","Độ phân giải":"FHD 1920x1080","Tần số quét":"240Hz","Thời gian phản hồi":"1ms MPRT"}', NOW(), NOW()),
(66, 'Màn hình ASUS VY249HGR 24" IPS 165Hz', 'Màn hình gaming tầm trung lý tưởng: IPS tươi sáng, 165Hz mượt mà, giá phải chăng cho sinh viên và game thủ mới.', 3290000, 2890000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081465/techshop/products/product_66.jpg', 'ASUS', 'ASUS-VY249HGR', 'man-hinh-asus-vy249hgr-165hz', 4, 1, '{"Kích thước":"23.8 inch","Tấm nền":"IPS","Độ phân giải":"FHD 1920x1080","Tần số quét":"165Hz","Thời gian phản hồi":"1ms MPRT"}', NOW(), NOW()),
(24, 'Bàn phím cơ AKKO 3087 v2 DS Midnight', 'Bàn phím cơ TKL gọn nhẹ, keycap PBT Double-shot bền màu, switch Akko Pink v2 gõ êm.', 1290000, 990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080099/techshop/products/product_24.jpg', 'AKKO', 'AKKO-3087-MN', 'ban-phim-co-akko-3087-v2-midnight', 5, 1, '{"Layout":"TKL 87 phím","Switch":"Akko Pink v2","Keycap":"PBT Double-Shot","Kết nối":"USB Type-C rời","Đèn":"RGB"}', NOW(), NOW()),
(25, 'Bàn phím cơ không dây Aula F75 Black RGB', 'Gasket mount gõ siêu êm, núm xoay đa phương tiện, 3 chế độ kết nối tiện lợi.', 1790000, 1390000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080102/techshop/products/product_25.png', 'Aula', 'AULA-F75-BLK', 'ban-phim-co-aula-f75-black', 5, 1, '{"Layout":"75% 80 phím","Switch":"LEOBOG Reaper","Kết nối":"Type-C / 2.4G / Bluetooth","Pin":"4000mAh","Đèn":"RGB"}', NOW(), NOW()),
(26, 'Bàn phím cơ Keychron K2 Pro RGB Aluminium', 'Khung nhôm cao cấp, hot-swap dễ đổi switch, 3 chế độ kết nối, macOS và Windows tương thích.', 2490000, 2190000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080104/techshop/products/product_26.jpg', 'Keychron', 'KEYCHRON-K2-PRO', 'ban-phim-co-keychron-k2-pro', 5, 1, '{"Layout":"75% 84 phím","Switch":"Keychron K Pro Red (Hot-swap)","Kết nối":"Bluetooth 5.1 / USB-C","Khung":"Nhôm anodized","Đèn":"RGB"}', NOW(), NOW()),
(27, 'Bàn phím cơ Corsair K70 RGB PRO TKL', 'Corsair K70 Pro đỉnh cao: switch Cherry MX Speed Silver siêu nhạy, frame nhôm brushed sang trọng.', 3690000, 3290000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080107/techshop/products/product_27.png', 'Corsair', 'CORSAIR-K70-TKL', 'ban-phim-co-corsair-k70-rgb-pro', 5, 1, '{"Layout":"TKL 87 phím","Switch":"Cherry MX Speed Silver","Keycap":"PBT Double-Shot","Kết nối":"USB Type-A","Đèn":"RGB per-key"}', NOW(), NOW()),
(28, 'Bàn phím cơ AKKO 5075B Plus World Tour Tokyo', 'AKKO 5075B Plus gasket mount, knob đa năng, đèn RGB tuyệt đẹp, thiết kế Tokyo độc đáo.', 1990000, 1690000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080110/techshop/products/product_28.jpg', 'AKKO', 'AKKO-5075B-TOKYO', 'ban-phim-co-akko-5075b-tokyo', 5, 1, '{"Layout":"75% 80 phím","Switch":"Akko CS Jelly Pink","Kết nối":"Type-C / 2.4G / Bluetooth","Cấu trúc":"Gasket Mount","Đèn":"RGB"}', NOW(), NOW()),
(67, 'Bàn phím cơ Logitech G512 Carbon RGB GX Blue', 'Logitech G512 switch GX Blue click êm ái, đèn RGB Lightsync đồng bộ, khung nhôm chắc chắn bền bỉ.', 2490000, 1990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081468/techshop/products/product_67.png', 'Logitech', 'LOGITECH-G512-GXBLUE', 'ban-phim-co-logitech-g512-gx-blue', 5, 1, '{"Layout":"Full-size 104 phím","Switch":"Logitech GX Blue","Keycap":"ABS","Kết nối":"USB Type-A","Đèn":"RGB Lightsync per-key"}', NOW(), NOW()),
(68, 'Bàn phím cơ Razer Huntsman V3 Pro Mini 60%', 'Razer Huntsman V3 Pro Mini dạng 60% siêu gọn, switch Analog quang học mới nhất, phản hồi cực nhanh 0.2ms.', 4490000, 3990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081471/techshop/products/product_68.png', 'Razer', 'RAZER-HUNTSMAN-V3-MINI', 'ban-phim-co-razer-huntsman-v3-pro-mini', 5, 1, '{"Layout":"60% 61 phím","Switch":"Razer Analog Optical v2","Keycap":"PBT Doubleshot","Kết nối":"USB Type-C","Đèn":"Razer Chroma RGB"}', NOW(), NOW()),
(69, 'Bàn phím cơ Leobog Hi86 TKL Gasket', 'Leobog Hi86 gasket mount siêu mềm mại, hỗ trợ hot-swap, 3 chế độ kết nối, đánh đổi tuyệt vời cho giá tiền.', 1490000, 1190000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081473/techshop/products/product_69.png', 'Leobog', 'LEOBOG-HI86-TM', 'ban-phim-co-leobog-hi86-gasket', 5, 1, '{"Layout":"TKL 87 phím","Switch":"Leobog Reaper Linear (Hot-swap)","Kết nối":"Type-C / 2.4G / Bluetooth","Cấu trúc":"Gasket Mount","Đèn":"RGB"}', NOW(), NOW());
INSERT INTO products (id, name, description, price, sale_price, image_url, brand, sku, slug, category_id, active, specifications, created_at, updated_at) VALUES
(29, 'Chuột không dây Logitech G304 LightSpeed Black', 'Chuột gaming quốc dân không dây siêu nhạy, pin 250 giờ, sensor HERO 12K DPI chính xác.', 1090000, 890000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080113/techshop/products/product_29.jpg', 'Logitech', 'LOGITECH-G304', 'chuot-khong-day-logitech-g304', 6, 1, '{"Sensor":"HERO 12K DPI","Kết nối":"Lightspeed 2.4G","Pin":"250 giờ","Trọng lượng":"99g","Số nút":"6"}', NOW(), NOW()),
(30, 'Chuột Razer DeathAdder Essential Black', 'Form tay phải công thái học hoàn hảo, mắt đọc quang học 6400 DPI cho game FPS chuẩn xác.', 690000, 390000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080225/techshop/products/product_30.png', 'Razer', 'RAZER-DA-ESSENTIAL', 'chuot-razer-deathadder-essential', 6, 1, '{"Sensor":"Optical 6400 DPI","Kết nối":"USB có dây","Trọng lượng":"96g","Switch":"Razer Mechanical"}', NOW(), NOW()),
(31, 'Chuột không dây Logitech MX Master 3S', 'Chuột văn phòng cao cấp: cuộn siêu nhanh MagSpeed, 8K DPI, kết nối đa thiết bị Bolt & Bluetooth.', 2290000, 1990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080115/techshop/products/product_31.jpg', 'Logitech', 'LOGITECH-MX-M3S', 'chuot-logitech-mx-master-3s', 6, 1, '{"Sensor":"Darkfield 8K DPI","Kết nối":"Logi Bolt / Bluetooth","Pin":"70 ngày (sạc USB-C)","Số nút":"7"}', NOW(), NOW()),
(32, 'Chuột gaming Razer Basilisk V3 Pro', 'Razer Basilisk V3 Pro không dây: HyperScroll Tilt Wheel, 11 nút lập trình, sạc không dây.', 2890000, 2490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080226/techshop/products/product_32.png', 'Razer', 'RAZER-BASILISK-V3P', 'chuot-razer-basilisk-v3-pro', 6, 1, '{"Sensor":"Focus Pro 30K DPI","Kết nối":"HyperSpeed Wireless / Bluetooth / USB","Pin":"90 giờ","Số nút":"11"}', NOW(), NOW()),
(33, 'Chuột gaming SteelSeries Rival 3', 'Chuột gaming giá sinh viên, TrueMove Core 8500 DPI, thiết kế nhẹ chỉ 77g đa năng.', 590000, 490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080117/techshop/products/product_33.jpg', 'Steelseries', 'SS-RIVAL-3', 'chuot-steelseries-rival-3', 6, 1, '{"Sensor":"TrueMove Core 8500 DPI","Kết nối":"USB có dây","Trọng lượng":"77g","Số nút":"6"}', NOW(), NOW()),
(34, 'Chuột gaming ASUS ROG Keris Wireless', 'ROG Keris không dây nhẹ chỉ 79g, cổng USB-C, hot-swap micro-switch, sạc nhanh tiện lợi.', 1990000, 1690000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080119/techshop/products/product_34.jpg', 'ASUS', 'ASUS-ROG-KERIS-WL', 'chuot-asus-rog-keris-wireless', 6, 1, '{"Sensor":"ROG AimPoint 36K DPI","Kết nối":"2.4GHz / Bluetooth / USB-C","Trọng lượng":"79g","Pin":"78 giờ"}', NOW(), NOW()),
(70, 'Chuột gaming ASUS TUF Gaming M4 Wireless', 'TUF M4 Wireless nhẹ chỉ 85g, pin 83 giờ, kết nối 2.4G + Bluetooth, chống nước IP54 bền bỉ.', 1290000, 1090000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081475/techshop/products/product_70.jpg', 'ASUS', 'ASUS-TUF-M4-WL', 'chuot-asus-tuf-gaming-m4-wireless', 6, 1, '{"Sensor":"8000 DPI","Kết nối":"2.4G Wireless + Bluetooth","Trọng lượng":"85g","Pin":"83 giờ","Chống nước":"IP54"}', NOW(), NOW()),
(71, 'Chuột văn phòng Logitech M650 Signature Graphite', 'Logitech M650 yên tĩnh không gây tiếng ồn, công thái học tự nhiên, tương thích đa thiết bị Bolt & Bluetooth.', 790000, 649000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081478/techshop/products/product_71.jpg', 'Logitech', 'LOGITECH-M650-GRAPHITE', 'chuot-logitech-m650-signature', 6, 1, '{"Sensor":"2000 DPI","Kết nối":"Logi Bolt / Bluetooth","Trọng lượng":"101g","Pin":"24 tháng (AA)","Tính năng":"Silent Click"}', NOW(), NOW()),
(35, 'Tai nghe Gaming HyperX Cloud II Red', 'Âm thanh vòm 7.1 ảo, driver 53mm, khung nhôm siêu bền, đệm tai da êm ái.', 2490000, 1790000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080121/techshop/products/product_35.jpg', 'HyperX', 'HYPERX-CLOUD-II', 'tai-nghe-hyperx-cloud-ii', 7, 1, '{"Driver":"53mm đất hiếm","Kết nối":"Jack 3.5mm + USB 7.1","Trọng lượng":"320g","Microphone":"Tháo rời linh hoạt"}', NOW(), NOW()),
(36, 'Tai nghe không dây Logitech G435 Lightspeed', 'Siêu nhẹ 165g, kết nối không dây kép Lightspeed và Bluetooth, pin 18 giờ.', 2290000, 1690000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080123/techshop/products/product_36.jpg', 'Logitech', 'LOGITECH-G435', 'tai-nghe-logitech-g435-wireless', 7, 1, '{"Driver":"40mm","Kết nối":"Lightspeed 2.4G + Bluetooth","Trọng lượng":"165g","Pin":"18 giờ"}', NOW(), NOW()),
(37, 'Tai nghe Gaming Razer BlackShark V2 X', 'Driver TriForce Titanium 50mm, tần số đáp ứng 12Hz-28kHz, mic chống ồn dứt khoát.', 990000, 790000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080127/techshop/products/product_37.png', 'Razer', 'RAZER-BS-V2X', 'tai-nghe-razer-blackshark-v2x', 7, 1, '{"Driver":"TriForce Titanium 50mm","Kết nối":"Jack 3.5mm","Trọng lượng":"240g","Microphone":"Cardioid có thể tháo rời"}', NOW(), NOW()),
(38, 'Tai nghe gaming SteelSeries Arctis Nova 3', 'Thiết kế Nova Architecture, loa 40mm ClearCast Gen 2, âm thanh Spatial Audio thực tế.', 1490000, 1190000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080129/techshop/products/product_38.jpg', 'Steelseries', 'SS-ARCTIS-NOVA3', 'tai-nghe-steelseries-arctis-nova3', 7, 1, '{"Driver":"40mm Nova","Kết nối":"Jack 3.5mm","Trọng lượng":"220g","Microphone":"ClearCast Gen 2 AI"}', NOW(), NOW()),
(39, 'Tai nghe Sony WH-1000XM5 Bluetooth ANC', 'Chống ồn chủ động ANC đỉnh nhất phân khúc, pin 30 giờ, sạc nhanh 3 phút dùng 3 giờ.', 8990000, 7490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080132/techshop/products/product_39.jpg', 'Sony', 'SONY-WH1000XM5', 'tai-nghe-sony-wh-1000xm5', 7, 1, '{"Driver":"30mm","Kết nối":"Bluetooth 5.2 + Jack 3.5mm","Pin":"30 giờ (ANC bật)","Chống ồn":"ANC Dual Noise Sensor"}', NOW(), NOW()),
(40, 'Tai nghe JBL Quantum 800 Wireless', 'JBL QuantumSOUND Signature, ANC chủ động, đàm thoại clear mic, kết nối 2.4G không dây.', 2190000, 1790000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080134/techshop/products/product_40.jpg', 'JBL', 'JBL-QUANTUM-800', 'tai-nghe-jbl-quantum-800', 7, 1, '{"Driver":"50mm","Kết nối":"2.4G Wireless + Bluetooth 5.0 + Jack 3.5mm","Pin":"14 giờ (2.4G)"}', NOW(), NOW()),
(41, 'Ghế gaming Warrior Raider Series WGC206 Black/Red', 'Khung kim loại vững chắc, đệm đúc nguyên khối chống xẹp lún và da PU cao cấp chống xước.', 3290000, 2790000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080136/techshop/products/product_41.jpg', 'Warrior', 'WARRIOR-WGC206', 'ghe-gaming-warrior-raider-wgc206', 8, 1, '{"Chất liệu":"Da PU cao cấp","Tải tối đa":"120kg","Góc ngả lưng":"135°","Trục thủy lực":"Class 4"}', NOW(), NOW()),
(42, 'Ghế gaming DXRacer Formula F11-NR Black/Red', 'DXRacer dòng Formula công thái học, hỗ trợ lưng và cổ xuất sắc cho game thủ chuyên nghiệp.', 5490000, 4890000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080138/techshop/products/product_42.jpg', 'DXRacer', 'DXR-F11-NR', 'ghe-gaming-dxracer-formula-f11', 8, 1, '{"Chất liệu":"Da PU + Lưới","Tải tối đa":"130kg","Góc ngả lưng":"135°","Tay ghế":"3D điều chỉnh"}', NOW(), NOW()),
(43, 'Ghế gaming E-Dra EGC211 Black/Blue', 'E-Dra EGC211 tay ghế 4D linh hoạt, gối đầu và tựa lưng thoải mái, phù hợp nhiều vóc người.', 2490000, 2190000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080141/techshop/products/product_43.png', 'E-Dra', 'EDRA-EGC211-BB', 'ghe-gaming-edra-egc211', 8, 1, '{"Chất liệu":"Da PU","Tải tối đa":"120kg","Tay ghế":"4D","Góc ngả lưng":"160°"}', NOW(), NOW()),
(44, 'Ghế gaming Razer Iskur V2 Ergonomic', 'Razer Iskur V2 thiết kế công thái học chuyên nghiệp, tựa lưng vải thoáng khí, hỗ trợ lumbar tích hợp.', 13990000, 12490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080144/techshop/products/product_44.png', 'Razer', 'RAZER-ISKUR-V2', 'ghe-gaming-razer-iskur-v2', 8, 1, '{"Chất liệu":"Vải EPU","Tải tối đa":"136kg","Hỗ trợ lưng":"Lumbar tích hợp có thể điều chỉnh","Tay ghế":"4D"}', NOW(), NOW()),
(45, 'Bàn gaming E-Dra EGT1460 Black 140cm', 'Bàn gaming rộng 140cm, chân thép vững chắc, mặt bàn phủ carbon fiber giả, có móc tai nghe.', 2190000, 1890000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080145/techshop/products/product_45.jpg', 'E-Dra', 'EDRA-EGT1460', 'ban-gaming-edra-egt1460', 8, 1, '{"Kích thước":"140 x 60 x 75 cm","Chất liệu":"MDF phủ carbon fiber","Chân":"Thép sơn tĩnh điện"}', NOW(), NOW()),
(46, 'Máy chơi game cầm tay ASUS ROG Ally RC71L', 'Trải nghiệm game PC mọi lúc mọi nơi, màn hình 120Hz sắc nét, chạy Windows 11 bản đầy đủ.', 19990000, 15990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080147/techshop/products/product_46.png', 'ASUS', 'ASUS-ROG-ALLY', 'may-choi-game-asus-rog-ally', 9, 1, '{"CPU":"AMD Ryzen Z1 Extreme","RAM":"16GB LPDDR5","SSD":"512GB PCIe 4.0","Màn hình":"7 inch FHD 120Hz Touch","OS":"Windows 11 Home"}', NOW(), NOW()),
(47, 'Tay cầm chơi game Sony DualSense Edge PS5', 'Tay cầm flagship PS5, nút lưng tùy chỉnh, cần analog có thể thay, hành trình trigger điều chỉnh.', 4290000, 3790000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080151/techshop/products/product_47.png', 'Sony', 'SONY-DUALSENSE-EDGE', 'tay-cam-sony-dualsense-edge-ps5', 9, 1, '{"Tương thích":"PS5 / PC","Nút lưng":"2 nút tùy biến","Trigger":"Điều chỉnh hành trình"}', NOW(), NOW()),
(48, 'Tay cầm Xbox Wireless Controller Carbon Black', 'Tay cầm Xbox Series X/S chính hãng Microsoft, kết nối Xbox Wireless, pin AA 40 giờ.', 1590000, 1390000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080156/techshop/products/product_48.png', 'Microsoft', 'MS-XBOX-CTRL-BLK', 'tay-cam-xbox-wireless-carbon', 9, 1, '{"Tương thích":"Xbox Series X/S / Xbox One / Windows 10/11","Kết nối":"Xbox Wireless 2.4G + Bluetooth","Pin":"AA x2 khoảng 40 giờ"}', NOW(), NOW()),
(49, 'Máy chơi game Nintendo Switch OLED White', 'Nintendo Switch OLED màn 7 inch sống động, bộ nhớ trong 64GB, dock mới có cổng LAN.', 8490000, 7990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080158/techshop/products/product_49.png', 'Nintendo', 'NINTENDO-SW-OLED', 'may-choi-game-nintendo-switch-oled', 9, 1, '{"Màn hình":"7 inch OLED 720p","RAM":"4GB","Bộ nhớ trong":"64GB (expandable)","Pin":"4.5-9 giờ"}', NOW(), NOW()),
(50, 'Tay cầm SteelSeries Stratus Duo Windows/Android', 'Hỗ trợ Windows, Android, Steam; kết nối 2.4G không dây và Bluetooth đồng thời tiện dụng.', 1290000, 1090000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783080170/techshop/products/product_50.png', 'Steelseries', 'SS-STRATUS-DUO', 'tay-cam-steelseries-stratus-duo', 9, 1, '{"Tương thích":"Windows / Android / Steam","Kết nối":"2.4G Wireless + Bluetooth","Pin":"20 giờ (AA)"}', NOW(), NOW()),
(72, 'Máy chơi game cầm tay MSI Claw A1M', 'MSI Claw A1M - máy chơi game cầm tay đầu tiên dùng Intel Core Ultra, màn hình 7 inch FHD 120Hz cảm ứng, chạy Windows 11.', 17990000, 15990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081480/techshop/products/product_72.png', 'MSI', 'MSI-CLAW-A1M', 'may-choi-game-msi-claw-a1m', 9, 1, '{"CPU":"Intel Core Ultra 5 135H","RAM":"16GB LPDDR5","SSD":"512GB NVMe","Màn hình":"7 inch FHD 120Hz Touch","OS":"Windows 11 Home"}', NOW(), NOW());
INSERT INTO products (id, name, description, price, sale_price, image_url, brand, sku, slug, category_id, active, specifications, created_at, updated_at) VALUES
(73, 'Đế sạc không dây Anker 313 MagSafe 15W', 'Sạc không dây MagSafe 15W siêu nhanh cho iPhone, tương thích Qi 10W cho Android, thiết kế gọn nhẹ mang theo.', 390000, 290000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081482/techshop/products/product_73.jpg', 'Anker', 'ANKER-313-MAGSAFE', 'de-sac-khong-day-anker-313-magsafe', 10, 1, '{"Công suất":"15W (MagSafe) / 10W (Qi)","Cổng vào":"USB-C","Tương thích":"iPhone 12+ / Android Qi"}', NOW(), NOW()),
(74, 'Balo laptop Targus 15.6 inch TSB910', 'Balo Targus TSB910 ngăn laptop đệm dày, ngăn iPad riêng, chất liệu chống nước, khóa TSA an toàn khi đi máy bay.', 1490000, 1190000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081485/techshop/products/product_74.jpg', 'Targus', 'TARGUS-TSB910', 'balo-laptop-targus-15-inch-tsb910', 10, 1, '{"Kích thước":"Phù hợp laptop 15.6 inch","Chất liệu":"Polyester chống nước","Dung tích":"26L","Tính năng":"Khóa TSA, ngăn USB charging"}', NOW(), NOW()),
(75, 'Bàn phím + chuột không dây Logitech MK470', 'Combo bộ bàn phím chuột Logitech MK470 siêu mỏng, silent click êm ái, kết nối 1 đầu USB Logi Bolt tiện lợi.', 990000, 799000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081486/techshop/products/product_75.jpg', 'Logitech', 'LOGITECH-MK470-SLIM', 'combo-logitech-mk470-slim-wireless', 10, 1, '{"Bàn phím":"Full-size slim silent","Chuột":"M350s 4000DPI","Kết nối":"Logi Bolt USB","Pin":"Bàn phím 36 tháng / Chuột 24 tháng"}', NOW(), NOW()),
(76, 'Kệ đỡ laptop nhôm Ugreen CM612 điều chỉnh 6 mức', 'Kệ nhôm Ugreen 6 mức độ cao, tản nhiệt tốt, gấp gọn bỏ túi, phù hợp laptop 11-17 inch dùng văn phòng và nhà.', 590000, 449000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081488/techshop/products/product_76.png', 'Ugreen', 'UGREEN-CM612-STAND', 'ke-do-laptop-ugreen-cm612-nhom', 10, 1, '{"Vật liệu":"Hợp kim nhôm","Điều chỉnh":"6 mức góc","Tương thích":"Laptop 11-17 inch","Tải tối đa":"8 kg"}', NOW(), NOW()),
(77, 'SSD Samsung 990 Pro 1TB PCIe 5.0 NVMe', 'Samsung 990 Pro tốc độ đọc 7450 MB/s, ghi 6900 MB/s - nhanh nhất trong phân khúc NVMe Gen 5 hiện tại.', 3490000, 2990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081490/techshop/products/product_77.png', 'Samsung', 'SAMSUNG-990PRO-1TB', 'ssd-samsung-990-pro-1tb-nvme', 11, 1, '{"Dung lượng":"1TB","Chuẩn":"NVMe PCIe 5.0","Tốc độ đọc":"7450 MB/s","Tốc độ ghi":"6900 MB/s","Form factor":"M.2 2280"}', NOW(), NOW()),
(78, 'SSD Kingston NV3 1TB PCIe 4.0 NVMe', 'Kingston NV3 giá tốt nhất tầm phổ thông: PCIe 4.0 tốc độ 6000 MB/s, bảo hành 3 năm đáng tin cậy.', 1490000, 1190000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081493/techshop/products/product_78.png', 'Kingston', 'KINGSTON-NV3-1TB', 'ssd-kingston-nv3-1tb-nvme', 11, 1, '{"Dung lượng":"1TB","Chuẩn":"NVMe PCIe 4.0","Tốc độ đọc":"6000 MB/s","Tốc độ ghi":"4000 MB/s","Form factor":"M.2 2280"}', NOW(), NOW()),
(79, 'SSD Corsair MP600 Core XT 1TB PCIe 4.0', 'Corsair MP600 Core XT cân bằng tốt giữa tốc độ và nhiệt độ, lý tưởng cho gaming và content creation.', 1890000, 1590000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081495/techshop/products/product_79.png', 'Corsair', 'CORSAIR-MP600-CORE-1TB', 'ssd-corsair-mp600-core-1tb', 11, 1, '{"Dung lượng":"1TB","Chuẩn":"NVMe PCIe 4.0 x4","Tốc độ đọc":"5000 MB/s","Tốc độ ghi":"4400 MB/s","Form factor":"M.2 2280"}', NOW(), NOW()),
(80, 'RAM Corsair Dominator Titanium Black 32GB DDR5 6000MHz', 'Corsair Dominator Titanium flagship DDR5: đèn RGB sống động 12 vùng, tốc độ 6000MHz CL30 cực nhanh cho gaming.', 4290000, 3790000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081499/techshop/products/product_80.png', 'Corsair', 'CORSAIR-DOM-TIT-32G-6000', 'ram-corsair-dominator-titanium-32gb-ddr5', 11, 1, '{"Dung lượng":"32GB (2x16GB)","Loại":"DDR5","Tốc độ":"6000MHz","Latency":"CL30","Điện áp":"1.35V","Đèn":"RGB 12 vùng"}', NOW(), NOW()),
(81, 'Mainboard ASUS ROG Maximus Z790 Hero DDR5', 'ROG Maximus Z790 Hero flagship cho Intel Gen 13/14: 20+1 pha nguồn, M.2 PCIe 5.0, Thunderbolt 4 đầy đủ.', 15990000, 13990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081504/techshop/products/product_81.jpg', 'ASUS', 'ASUS-ROG-Z790-HERO', 'mainboard-asus-rog-maximus-z790-hero', 12, 1, '{"Socket":"LGA1700","Chipset":"Intel Z790","Loại RAM":"DDR5 (4x DIMM)","Khe M.2":"5 khe PCIe 5.0/4.0","USB":"Thunderbolt 4, USB 3.2 Gen 2x2"}', NOW(), NOW()),
(82, 'Mainboard Gigabyte Z790 AORUS Elite AX DDR5', 'Gigabyte Z790 AORUS Elite AX: hỗ trợ PCIe 5.0, WiFi 6E tích hợp, 16+1+2 pha nguồn mạnh mẽ cho CPU thế hệ 13-14.', 7990000, 6990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081527/techshop/products/product_82.png', 'Gigabyte', 'GIGABYTE-Z790-AORUS-ELITE', 'mainboard-gigabyte-z790-aorus-elite', 12, 1, '{"Socket":"LGA1700","Chipset":"Intel Z790","Loại RAM":"DDR5","Khe M.2":"4 khe","WiFi":"WiFi 6E tích hợp"}', NOW(), NOW()),
(83, 'Card đồ họa ASUS ROG Astral RTX 5090 32GB', 'ASUS ROG Astral RTX 5090 - card đồ họa mạnh nhất thế giới hiện tại: GDDR7 32GB, 4nm Blackwell, sức mạnh AI đỉnh cao.', 89990000, 84990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081530/techshop/products/product_83.png', 'ASUS', 'ASUS-RTX5090-ASTRAL-32G', 'card-do-hoa-asus-rog-rtx-5090-32gb', 12, 1, '{"GPU":"NVIDIA RTX 5090","VRAM":"32GB GDDR7","Bus":"512-bit","Chuẩn kết nối":"PCIe 5.0 x16","Điện năng TDP":"575W"}', NOW(), NOW()),
(84, 'CPU Intel Core i7-14700F (20 nhân, up to 5.4GHz)', 'Intel Core i7-14700F 20 nhân (8P+12E), boost 5.4GHz, lý tưởng cho dựng video 4K, gaming và đa nhiệm nặng.', 8490000, 7490000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081533/techshop/products/product_84.png', 'Intel', 'INTEL-I7-14700F', 'cpu-intel-core-i7-14700f', 12, 1, '{"Nhân/Luồng":"20C/28T (8P+12E)","Clock cơ sở":"2.1GHz","Boost tối đa":"5.4GHz","Cache":"33MB Intel Smart","Socket":"LGA1700","TDP":"65W"}', NOW(), NOW()),
(85, 'Loa vi tính Edifier MR4 Studio Monitor', 'Edifier MR4 loa monitor studio 2.0 cho nhà: âm thanh chuẩn phòng thu, đầu vào RCA/AUX/Bluetooth tiện dụng.', 2490000, 1990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081534/techshop/products/product_85.jpg', 'Edifier', 'EDIFIER-MR4', 'loa-edifier-mr4-studio-monitor', 13, 1, '{"Cấu hình":"2.0","Công suất":"2x21W","Tần số":"50Hz-40kHz","Kết nối":"RCA, AUX 3.5mm, Bluetooth 5.1","Kích thước":"177x268x214mm"}', NOW(), NOW()),
(86, 'Micro thu âm HyperX QuadCast 2S RGB USB', 'HyperX QuadCast 2S nâng cấp: LED RGB sống động, 4 chế độ pickup pattern, chân đỡ chống rung tích hợp tiện lợi.', 3490000, 2990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081538/techshop/products/product_86.png', 'HyperX', 'HYPERX-QUADCAST-2S', 'micro-hyperx-quadcast-2s-rgb', 13, 1, '{"Loại":"Condenser USB","Mẫu thu":"Cardioid / Bidirectional / Stereo / Omnidirectional","Kết nối":"USB-C","Tần số":"20Hz-20kHz","Đèn":"RGB"}', NOW(), NOW()),
(87, 'Webcam Logitech Brio 4K Ultra HD Pro', 'Logitech Brio 4K đỉnh nhất: quay 4K@30fps hoặc 1080p@90fps, HDR, autofocus, Windows Hello chính hãng.', 4990000, 3990000, 'https://res.cloudinary.com/dpf8w7bj6/image/upload/v1783081541/techshop/products/product_87.png', 'Logitech', 'LOGITECH-BRIO-4K', 'webcam-logitech-brio-4k-ultra-hd', 13, 1, '{"Độ phân giải":"4K@30fps / 1080p@90fps","Cảm biến":"Sony Exmor CMOS","Tính năng":"HDR, RightLight 3, Windows Hello","Kết nối":"USB-C","Góc nhìn":"90°"}', NOW(), NOW());
